function updateEffects(dt){const fxdt=dt*BOARD_FX_SPEED;shimmerClock+=fxdt;const ease=Math.min(1,fxdt/70),now=performance.now();if(now>enemyLagHoldUntil)enemyHpLagValue+=(Math.max(0,enemy.hp)-enemyHpLagValue)*Math.min(1,dt/180);if(now>playerLagHoldUntil)playerHpLagValue+=(playerHp-playerHpLagValue)*Math.min(1,dt/180);comboTimer=Math.max(0,comboTimer-dt);if(comboTimer===0&&comboCount)resetCombo();if(overdriveUntil&&now>=overdriveUntil){overdriveUntil=0;overdriveMeter=0;document.body.classList.remove('overdrive')}pieceFx.nudgeX*=1-ease;pieceFx.nudgeY*=1-ease;pieceFx.spin*=1-ease;pieceFx.squash*=Math.max(0,1-fxdt/95);pieceFx.flash*=Math.max(0,1-fxdt/115);pieceFx.spawn*=Math.max(0,1-fxdt/120);particles.forEach(p=>{p.x+=p.vx*BOARD_FX_SPEED;p.y+=p.vy*BOARD_FX_SPEED;p.vy+=.12*BOARD_FX_SPEED;p.life-=fxdt;if(p.chunk)p.rot=(p.rot||0)+(p.rotSpeed||0)*BOARD_FX_SPEED});particles=particles.filter(p=>p.life>0);trails.forEach(t=>t.life-=fxdt);trails=trails.filter(t=>t.life>0);floaters.forEach(f=>{f.y-=fxdt*.045;f.life-=fxdt});floaters=floaters.filter(f=>f.life>0)}
