function drawJesterStatic(preview,pctx){const tick=Math.floor(performance.now()/75),palette=['#46425e','#15788c','#00b9be','#ffeecc','#ffb0a3','#ff6973'];for(let y=0;y<preview.height;y+=4)for(let x=0;x<preview.width;x+=4){const noise=(x*13+y*7+tick*17+(x*y)%19)%palette.length;pctx.fillStyle=palette[noise];pctx.globalAlpha=.35+((noise+tick)%3)*.18;pctx.fillRect(x,y,4,4)}pctx.globalAlpha=1;const band=(tick*7)%preview.height;pctx.fillStyle='#ffeecc';pctx.globalAlpha=.48;pctx.fillRect(0,band,preview.width,3);pctx.fillStyle='#46425e';pctx.fillRect(0,(band+5)%preview.height,preview.width,2);pctx.globalAlpha=1}
